-- DGMS Board of Mining Examinations notice of 8 Oct 2026. Run once, AFTER the PDF is on docs.mangalamcoal.com/regs/ and BEFORE
-- the site is rebuilt: the library page is built from this table. download_url and file_size_kb are not in the seed.
begin;
insert into public.regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, download_url, file_size_kb) values
  ('bme-notice-offline-exemption-basis-competency-certificates-2026', 'Board of Mining Examinations Notice — Offline Applications for Competency Certificates on Exemption Basis (CMR 2017 and MMR 1961)', 'dgms_notification', 'Notice of 8 October 2026 from the Board of Mining Examinations (Coal & Metal). Because the online Examination and Certification Portal is not available for fresh registration or applications, candidates eligible for a statutory competency certificate on exemption basis under the Coal Mines Regulations, 2017 or the Metalliferous Mines Regulations, 1961 may apply offline in Form-II, with original documents for verification, one set of self-certified photocopies, proof of the examination fee and four attested photographs. The arrangement lasts until the online platform is operational or until further orders.', null, 'DGMS', '2026-10-08', 'in_force', 'Interim arrangement: applies until the online platform is operational or until further orders.', 'https://www.dgms.gov.in/writereaddata/UploadFile/examNotification_08102026.pdf', 'examNotification_08102026.pdf', 2, 320, true, false, 'https://docs.mangalamcoal.com/regs/bme-notice-offline-exemption-basis-competency-certificates-2026.pdf', 384)
on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, download_url = excluded.download_url, file_size_kb = excluded.file_size_kb;
commit;
